INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Aufbauorganisation immer hierarchisch?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch flach sein"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend hierarchisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Aufbauorganisation?', 3, '[{"text": "Struktur schaffen", "correct": true, "because": "Definiert Verantwortlichkeiten"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Produktivität erzwingen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Aufbauorganisation?', 5, '[{"text": "Hierarchieebenen", "correct": true, "because": "Definiert Verantwortung"}, {"text": "Abteilungen", "correct": true, "because": "Fachliche Zuordnung"}, {"text": "Marketingstrategie", "correct": false, "because": "Kein Strukturelement"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Aufbauorganisation regelt Zuständigkeiten. b) Sie ist immer starr.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Aufbauorganisation?', 4, '[{"text": "Verantwortlichkeiten", "correct": false, "because": "Kern der Struktur"}, {"text": "Kommunikationswege", "correct": false, "because": "Wichtig für Ablauf"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Strukturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Aufbauorganisation Abteilungen umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Fachliche Einteilung"}, {"text": "Nein", "correct": false, "because": "Teil der Organisation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur gehört zur Aufbauorganisation?', 3, '[{"text": "Linienorganisation", "correct": true, "because": "Klarer Befehlsweg"}, {"text": "Projektorganisation", "correct": false, "because": "Temporär"}, {"text": "Marketingplan", "correct": false, "because": "Kein Strukturelement"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zu einer Matrixorganisation?', 5, '[{"text": "Doppelte Berichtslinien", "correct": true, "because": "Fachlich und hierarchisch"}, {"text": "Projektteams", "correct": true, "because": "Kombinierte Struktur"}, {"text": "Einheitliche Befehle", "correct": false, "because": "Nicht einheitlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Aufbauorganisation definiert Hierarchien. b) Sie ist nur für große Firmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für kleine Firmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Aufbauorganisation unwichtig?', 4, '[{"text": "Hierarchie", "correct": false, "because": "Strukturgrundlage"}, {"text": "Abteilungen", "correct": false, "because": "Fachliche Zuordnung"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Struktureinfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Aufbauorganisation flexibel?', 2, '[{"text": "Ja", "correct": true, "because": "Anpassbar an Bedarf"}, {"text": "Nein", "correct": false, "because": "Nicht statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Aufbauorganisation?', 4, '[{"text": "Klarheit", "correct": true, "because": "Definiert Zuständigkeiten"}, {"text": "Effiziente Koordination", "correct": true, "because": "Strukturierte Abläufe"}, {"text": "Schnellere Produktion", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Aufbauorganisation immer komplex ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann einfach sein"}, {"text": "Ja", "correct": false, "because": "Abhängig von Größe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Aufbauorganisation?', 3, '[{"text": "Verantwortlichkeiten", "correct": true, "because": "Kernaufgabe"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Aufbauorganisation regelt Berichtswege. b) Sie ist immer flach.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht immer flach"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine komplexe Aufbauorganisation?', 5, '[{"text": "Hoher Koordinationsaufwand", "correct": true, "because": "Viele Ebenen"}, {"text": "Langsame Entscheidungen", "correct": true, "because": "Hierarchie"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Eher starr"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Aufbauorganisation unwichtig?', 3, '[{"text": "Hierarchie", "correct": false, "because": "Strukturgrundlage"}, {"text": "Kommunikationswege", "correct": false, "because": "Notwendig"}, {"text": "Mitarbeiternamen", "correct": true, "because": "Kein Strukturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann die Aufbauorganisation flach sein?', 3, '[{"text": "Ja", "correct": true, "because": "Wenige Ebenen möglich"}, {"text": "Nein", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Aufbauorganisation Abläufe regelt?', 2, '[{"text": "Nein", "correct": true, "because": "Ablauforganisation zuständig"}, {"text": "Ja", "correct": false, "because": "Struktur, nicht Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur wähle ich für eine klare Befehlskette?', 4, '[{"text": "Linienorganisation", "correct": true, "because": "Direkte Hierarchie"}, {"text": "Matrixorganisation", "correct": false, "because": "Doppelte Linien"}, {"text": "Projektorganisation", "correct": false, "because": "Temporär"}]');
